/**
     * The size of the buffer used for memory accounting.
     * This buffer is used to locally track the memory accummulate during the executiong of
     * a search request before submitting the accumulated value to the circuit breaker.
     */
    public static final Setting<ByteSizeValue> MEMORY_ACCOUNTING_BUFFER_SIZE = Setting.byteSizeSetting(
        "search.memory_accounting_buffer_size",
        ByteSizeValue.of(32, ByteSizeUnit.KB),
        Property.Dynamic,
        Property.NodeScope
    );

public class MemoryAccountingBytesRefCountedTests extends ESTestCase {

    public void testNoMemoryAccounted() {
        CircuitBreaker breaker = new MockBigArrays.LimitedBreaker("test", ByteSizeValue.ofGb(1));
        MemoryAccountingBytesRefCounted refCounted = MemoryAccountingBytesRefCounted.create(breaker);
        refCounted.decRef();
        assertEquals(0, breaker.getUsed());
    }

    public void testMemoryAccounted() {
        CircuitBreaker breaker = new MockBigArrays.LimitedBreaker("test", ByteSizeValue.ofGb(1));
        MemoryAccountingBytesRefCounted refCounted = MemoryAccountingBytesRefCounted.create(breaker);
        refCounted.account(10, "test");
        assertEquals(10, breaker.getUsed());
    }

    public void testCloseInternalDecrementsBreaker() {
        CircuitBreaker breaker = new MockBigArrays.LimitedBreaker("test", ByteSizeValue.ofGb(1));
        MemoryAccountingBytesRefCounted refCounted = MemoryAccountingBytesRefCounted.create(breaker);
        refCounted.account(10, "test");
        refCounted.decRef();
        assertEquals(0, breaker.getUsed());
    }

    public void testBreakerNotDecrementedIfRefsRemaining() {
        CircuitBreaker breaker = new MockBigArrays.LimitedBreaker("test", ByteSizeValue.ofGb(1));
        MemoryAccountingBytesRefCounted refCounted = MemoryAccountingBytesRefCounted.create(breaker);
        refCounted.account(10, "test");
        refCounted.incRef(); // 2 refs
        assertEquals(10, breaker.getUsed());
        refCounted.decRef(); // 1 ref remaining so no decrementing is executed
        assertEquals(10, breaker.getUsed());
    }
}

private HitContext prepareHitContext(
        SearchContext context,
        boolean requiresSource,
        Profiler profiler,
        LeafNestedDocuments nestedDocuments,
        LeafStoredFieldLoader leafStoredFieldLoader,
        int docId,
        LeafReaderContext subReaderContext,
        SourceLoader.Leaf sourceLoader,
        IdLoader.Leaf idLoader,
        RankDoc rankDoc,
        CircuitBreaker circuitBreaker,
        boolean submitToCb,
        Consumer<Integer> memoryUsageBytesAccumulator,
        Supplier<Integer> accumulatedBytesInLeaf
    ) throws IOException {
        if (nestedDocuments.advance(docId - subReaderContext.docBase) == null) {
            return prepareNonNestedHitContext(
                requiresSource,
                profiler,
                leafStoredFieldLoader,
                docId,
                subReaderContext,
                sourceLoader,
                idLoader,
                rankDoc,
                circuitBreaker,
                submitToCb,
                memoryUsageBytesAccumulator,
                accumulatedBytesInLeaf
            );
        } else {
            return prepareNestedHitContext(
                context,
                requiresSource,
                profiler,
                docId,
                nestedDocuments,
                subReaderContext,
                leafStoredFieldLoader,
                rankDoc
            );
        }
    }

private final Supplier<Integer> getAndResetAccumulatedBytes = () -> {
                int bytesToSubmit = this.accumulatedBytesInLeaf;
                this.accumulatedBytesInLeaf = 0;
                return bytesToSubmit;
            };

/**
 * A ref counted object that accounts for memory usage in bytes and releases the
 * accounted memory from the circuit breaker when the reference count reaches zero.
 */
public final class MemoryAccountingBytesRefCounted extends AbstractRefCounted {

    private int bytes;
    private final CircuitBreaker breaker;

    private MemoryAccountingBytesRefCounted(int bytes, CircuitBreaker breaker) {
        this.bytes = bytes;
        this.breaker = breaker;
    }

    public static MemoryAccountingBytesRefCounted create(CircuitBreaker breaker) {
        return new MemoryAccountingBytesRefCounted(0, breaker);
    }

    public void account(int bytes, String label) {
        breaker.addEstimateBytesAndMaybeBreak(bytes, label);
        this.bytes += bytes;
    }

    @Override
    protected void closeInternal() {
        breaker.addWithoutBreaking(-bytes);
    }
}

/**
     * Resets the provided {@link HitContext} with information on the current
     * document. This includes the following:
     *   - Adding an initial {@link SearchHit} instance.
     *   - Loading the document source and setting it on {@link HitContext#source()}. This
     *     allows fetch subphases that use the hit context to access the preloaded source.
     */
    private static HitContext prepareNonNestedHitContext(
        boolean requiresSource,
        Profiler profiler,
        LeafStoredFieldLoader leafStoredFieldLoader,
        int docId,
        LeafReaderContext subReaderContext,
        SourceLoader.Leaf sourceLoader,
        IdLoader.Leaf idLoader,
        RankDoc rankDoc,
        CircuitBreaker circuitBreaker,
        boolean accountMemoryWithCircuitBreaker,
        Consumer<Integer> memoryUsageBytesAccumulator,
        Supplier<Integer> accumulatedBytesInLeaf
    ) throws IOException {
        int subDocId = docId - subReaderContext.docBase;

        leafStoredFieldLoader.advanceTo(subDocId);

        MemoryAccountingBytesRefCounted memAccountingRefCounted = null;
        RefCounted refCountedHit = null;
        if (accountMemoryWithCircuitBreaker) {
            memAccountingRefCounted = MemoryAccountingBytesRefCounted.create(circuitBreaker);
            refCountedHit = LeakTracker.wrap(memAccountingRefCounted);
        }
        String id = idLoader.getId(subDocId);
        if (id == null) {
            SearchHit hit = new SearchHit(docId, null, null, refCountedHit);
            // TODO: can we use real pooled buffers here as well?
            Source source = Source.lazy(
                lazyStoredSourceLoader(
                    profiler,
                    subReaderContext,
                    subDocId,
                    memAccountingRefCounted,
                    accountMemoryWithCircuitBreaker,
                    memoryUsageBytesAccumulator,
                    accumulatedBytesInLeaf
                )
            );
            return new HitContext(hit, subReaderContext, subDocId, Map.of(), source, rankDoc);
        } else {
            SearchHit hit = new SearchHit(docId, id, null, refCountedHit);
            Source source;
            if (requiresSource) {
                Timer timer = profiler.startLoadingSource();
                try {
                    source = sourceLoader.source(leafStoredFieldLoader, subDocId);
                    memoryUsageBytesAccumulator.accept(source.internalSourceRef().length());
                    if (accountMemoryWithCircuitBreaker) {
                        memAccountingRefCounted.account(accumulatedBytesInLeaf.get(), "fetch phase source loader");
                    }
                } catch (CircuitBreakingException e) {
                    hit.decRef();
                    throw e;
                } finally {
                    if (timer != null) {
                        timer.stop();
                    }
                }
            } else {
                source = Source.lazy(
                    lazyStoredSourceLoader(
                        profiler,
                        subReaderContext,
                        subDocId,
                        memAccountingRefCounted,
                        accountMemoryWithCircuitBreaker,
                        memoryUsageBytesAccumulator,
                        accumulatedBytesInLeaf
                    )
                );
            }
            return new HitContext(hit, subReaderContext, subDocId, leafStoredFieldLoader.storedFields(), source, rankDoc);
        }
    }

/**
     * The size of the buffer used for memory accounting.
     * This buffer is used to locally track the memory accummulate during the executiong of
     * a search request before submitting the accumulated value to the circuit breaker.
     */
    public static final Setting<ByteSizeValue> MEMORY_ACCOUNTING_BUFFER_SIZE = Setting.byteSizeSetting(
        "search.memory_accounting_buffer_size",
        ByteSizeValue.of(32, ByteSizeUnit.KB),
        Property.Dynamic,
        Property.NodeScope
    );

